const LANGS = ['de','fr','es','pt','ru','ja','ko','zh','zh-TW','he','tr','ar','vi','pl','it','th','id'];
function R(...vals) {
  const out = {};
  LANGS.forEach((lang, i) => { out[lang] = vals[i] ?? vals[0]; });
  return out;
}

